'use client';

import React from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Search, ShoppingCart, User, Package } from 'lucide-react';
import { CATEGORIES } from '../mock/data';

export const ShopHeader: React.FC = () => {
    const pathname = usePathname();

    return (
        <header className="bg-white border-b border-slate-100 sticky top-0 z-50">
            {/* Top Bar */}
            <div className="max-w-7xl mx-auto px-4 h-20 flex items-center justify-between gap-8">
                {/* Logo */}
                <Link href="/shop" className="flex items-center gap-2 group">
                    <div className="w-10 h-10 bg-emerald-600 rounded-xl flex items-center justify-center shadow-lg shadow-emerald-200 group-hover:scale-105 transition-transform">
                        <Package className="text-white w-6 h-6" />
                    </div>
                    <span className="text-2xl font-black text-slate-900 tracking-tighter">RestoPack</span>
                </Link>

                {/* Search Bar */}
                <div className="flex-1 max-w-2xl relative group hidden md:block">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5 group-focus-within:text-emerald-600 transition-colors" />
                    <input
                        type="text"
                        placeholder="Search supplies..."
                        className="w-full h-12 pl-12 pr-4 bg-slate-100 rounded-2xl border-none font-medium text-slate-900 placeholder:text-slate-400 focus:ring-2 focus:ring-emerald-600/20 focus:bg-white transition-all outline-none"
                    />
                </div>

                {/* Icons */}
                <div className="flex items-center gap-2">
                    <button className="p-3 hover:bg-slate-100 rounded-2xl text-slate-600 transition-colors relative">
                        <ShoppingCart className="w-6 h-6" />
                        <span className="absolute top-2 right-2 w-4 h-4 bg-emerald-600 text-white text-[10px] font-bold rounded-full flex items-center justify-center">0</span>
                    </button>
                    <button className="p-3 hover:bg-slate-100 rounded-2xl text-slate-600 transition-colors">
                        <User className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Navigation Tabs */}
            <div className="max-w-7xl mx-auto px-4 flex items-center border-t border-slate-50">
                {CATEGORIES.map((cat) => {
                    const isActive = pathname === `/shop/${cat.id}` || (pathname === '/shop' && cat.id === 'packaging');
                    return (
                        <Link
                            key={cat.id}
                            href={`/shop/${cat.id}`}
                            className={`px-8 py-4 text-sm font-black uppercase tracking-widest transition-all relative ${isActive
                                ? 'text-emerald-600'
                                : 'text-slate-400 hover:text-slate-700'
                                }`}
                        >
                            {cat.name}
                            {isActive && (
                                <div className="absolute bottom-0 left-0 right-0 h-1 bg-emerald-600 rounded-full mx-6" />
                            )}
                        </Link>
                    )
                })}
            </div>
        </header>
    );
};
